/* ============================================================
   VERSION HISTORY — histórico de versões (rede de segurança "A")
   ------------------------------------------------------------
   Guarda no próprio dispositivo as últimas versões do perfil, para você
   RESTAURAR caso algo se perca (apagou algo sem querer, ou um aparelho
   sobrescreveu o outro). Cada snapshot é COMPRIMIDO com gzip (CompressionStream),
   ficando ~5-10x menor — cabe com folga mesmo em perfis grandes.
   Gatilhos: antes de baixar da nuvem (cobre o clobber, por dispositivo),
   um backup automático por dia, e manual pelo botão em Configurações.
   100% no cliente, reversível, e não exige nada do Supabase.
   ============================================================ */
/* ═══════════════════ HISTORICO DE VERSOES (rede de seguranca) ═══════════════
   Antes: 1 foto por dia, 8 no total. Quem apagasse algo por engano de manha e
   percebesse a tarde so tinha a foto da meia-noite — perdia o dia inteiro de
   trabalho. Agora as fotos sao FREQUENTES (a cada 20 min de uso, e sempre que
   uma acao destrutiva acontece) e a lista se AUTOLIMPA:

     • JANELA de 7 dias — nada mais velho que isso e mantido; um backup de duas
       semanas atras nao ajuda e ocupa espaco.
     • PISO de 3 versoes — mesmo depois de 7 dias parado, voce sempre volta as
       tres ultimas fotos. A limpeza nunca deixa o usuario sem rede.
     • ORCAMENTO de espaco — o conjunto nunca passa de ~3 MB (ja comprimido em
       gzip). Estourou, as mais antigas saem primeiro.
   O resultado e uma protecao continua que nao cresce sem limite.
   ═══════════════════════════════════════════════════════════════════════════ */
const BackupHistory = {
  MAX: 24,                       // teto de fotos guardadas
  MIN_KEEP: 3,                   // nunca limpa abaixo disto, custe o que custar
  MAX_AGE_MS: 7 * 24 * 3600 * 1000,   // janela de 7 dias
  MAX_BYTES: 3 * 1024 * 1024,    // orcamento total (~3 MB comprimidos)
  AUTO_EVERY_MS: 20 * 60 * 1000, // foto automatica a cada 20 min de uso
  _key(id) { return 'diario-estudos:vhist:' + id; },
  _dayKey(id) { return 'diario-estudos:vhist-day:' + id; },
  _autoKey(id) { return 'diario-estudos:vhist-auto:' + id; },
  _list(id) { try { return JSON.parse(localStorage.getItem(this._key(id))) || []; } catch (_) { return []; } },

  /* Autolimpeza: idade > orcamento > teto, sempre respeitando MIN_KEEP.
     Roda antes de cada gravacao, entao a lista nunca "engorda calada". */
  _prune(arr) {
    if (!Array.isArray(arr)) return [];
    const agora = Date.now();
    // 1) idade — descarta o que passou da janela, preservando o piso
    let out = arr.filter(r => (agora - (r.ts || 0)) <= this.MAX_AGE_MS);
    if (out.length < this.MIN_KEEP) out = arr.slice(-this.MIN_KEEP);
    // 2) teto de quantidade
    while (out.length > this.MAX) out.shift();
    // 3) orcamento de espaco — as mais antigas saem primeiro
    const peso = (r) => ((r && r.data) ? String(r.data).length : 0) * 2; // UTF-16
    let total = out.reduce((a, r) => a + peso(r), 0);
    while (total > this.MAX_BYTES && out.length > this.MIN_KEEP) {
      total -= peso(out[0]);
      out.shift();
    }
    return out;
  },

  _save(id, arr) {
    arr = this._prune(arr);
    while (true) {
      try { localStorage.setItem(this._key(id), JSON.stringify(arr)); return true; }
      catch (e) { if (arr.length > 1) { arr.shift(); continue; } try { localStorage.removeItem(this._key(id)); } catch (_) { _quiet(_); } return false; }
    }
  },
  _b64enc(u8) { let s = ''; const CH = 0x8000; for (let i = 0; i < u8.length; i += CH) s += String.fromCharCode.apply(null, u8.subarray(i, i + CH)); return btoa(s); },
  _b64dec(b64) { const bin = atob(b64); const u8 = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i); return u8; },
  _fnv(str) { let h = 2166136261; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return (h >>> 0).toString(36); },
  async _gzip(str) {
    try {
      if (typeof CompressionStream === 'undefined') return { enc: 'raw', data: str };
      const cs = new CompressionStream('gzip');
      const ab = await new Response(new Blob([str]).stream().pipeThrough(cs)).arrayBuffer();
      return { enc: 'gz', data: this._b64enc(new Uint8Array(ab)) };
    } catch (_) { return { enc: 'raw', data: str }; }
  },
  async _gunzip(rec) {
    if (!rec) return null;
    if (rec.enc !== 'gz') return rec.data;
    try {
      const ds = new DecompressionStream('gzip');
      const ab = await new Response(new Blob([this._b64dec(rec.data)]).stream().pipeThrough(ds)).arrayBuffer();
      return new TextDecoder().decode(ab);
    } catch (_) { return null; }
  },
  // Cria uma versão do perfil ATIVO. Não duplica se for idêntica à última.
  async snapshot(note) {
    try {
      const id = ProfileManager.getActiveProfileId(); if (!id) return false;
      const backup = ProfileManager.exportProfile(id); if (!backup) return false;
      const json = JSON.stringify(backup.data || {});
      if (json === '{}' || json.length < 3) return false;
      const sig = this._fnv(json);
      const arr = this._list(id);
      if (arr.length && arr[arr.length - 1].sig === sig) return false;
      const packed = await this._gzip(json);
      arr.push({ ts: Date.now(), rev: ProfileManager.getRev(id), note: note || '', sig, enc: packed.enc, data: packed.data, chars: json.length });
      while (arr.length > this.MAX) arr.shift();
      this._save(id, arr);
      return true;
    } catch (_) { return false; }
  },
  maybeDailySnapshot() {
    try {
      const id = ProfileManager.getActiveProfileId(); if (!id) return;
      let last = null; try { last = localStorage.getItem(this._dayKey(id)); } catch (_) { _quiet(_); }
      const hoje = todayLocal();
      if (last !== hoje) {
        try { localStorage.setItem(this._dayKey(id), hoje); } catch (_) { _quiet(_); }
        this.snapshot('backup diário');
        return;
      }
      this.maybeAutoSnapshot();
    } catch (_) { _quiet(_); }
  },

  /* Foto periodica durante o uso. E o que transforma a rede de seguranca de
     "uma vez por dia" em "sempre por perto": no maximo 20 min de trabalho entre
     uma foto e outra. snapshot() ja ignora estados identicos, entao ficar com o
     app aberto sem mexer em nada NAO gera copias repetidas. */
  maybeAutoSnapshot() {
    try {
      const id = ProfileManager.getActiveProfileId(); if (!id) return false;
      let last = 0; try { last = parseInt(localStorage.getItem(this._autoKey(id)), 10) || 0; } catch (_) { _quiet(_); }
      if (Date.now() - last < this.AUTO_EVERY_MS) return false;
      try { localStorage.setItem(this._autoKey(id), String(Date.now())); } catch (_) { _quiet(_); }
      this.snapshot('cópia automática');
      return true;
    } catch (_) { return false; }
  },

  /* Foto AGORA, antes de uma acao destrutiva (limpar grade, excluir semana,
     apagar planejamento). E o backup que salva o dia — literalmente o caso de
     "limpei a grade sem querer". Nao espera intervalo nenhum. */
  async antesDe(acao) {
    try { return await this.snapshot('antes de ' + acao); } catch (_) { return false; }
  },

  // Faxina avulsa (chamada na abertura do app): aplica a janela de 7 dias.
  limpar() {
    try {
      const id = ProfileManager.getActiveProfileId(); if (!id) return;
      const arr = this._list(id);
      const limpo = this._prune(arr.slice());
      if (limpo.length !== arr.length) this._save(id, limpo);
    } catch (_) { _quiet(_); }
  },
  async buildBackup(id, ts) {
    const rec = this._list(id).find(r => r.ts === ts);
    if (!rec) return null;
    const json = await this._gunzip(rec);
    if (json == null) return null;
    let data; try { data = JSON.parse(json); } catch (_) { return null; }
    const meta = ProfileManager.getProfiles().find(p => p.id === id) || {};
    return { app: 'diario-estudos', kind: 'profile-backup', version: 1, exportedAt: new Date(rec.ts).toISOString(),
      profile: { nome: meta.nome, avatar: meta.avatar, cor: meta.cor }, data };
  },
  // Restaura uma versão SOBRE o perfil ativo (guarda o estado atual antes, então é reversível).
  async restore(id, ts) {
    const rec = this._list(id).find(r => r.ts === ts);
    if (!rec) return false;
    const json = await this._gunzip(rec);
    if (json == null) return false;
    let data; try { data = JSON.parse(json); } catch (_) { return false; }
    await this.snapshot('antes de restaurar uma versão');
    try {
      if (!window.RelationalStore) return false;
      await RelationalStore.replaceProfileFromPayload(id, data, { reason: 'session-backup-restore' });
      return true;
    } catch (e) { _quiet(e, 'backup-session-restore'); return false; }
  }
};
window.BackupHistory = BackupHistory;

src/js/61-session-guard.js.old:
/* ============================================================================
   SESSION GUARD — login único REAL entre dispositivos (via Supabase)
   ----------------------------------------------------------------------------
   Cada aparelho tem um device_id fixo. Ao logar (ou ao clicar em "Continuar
   neste aparelho"), este device "reivindica" a conta gravando seu id na tabela
   `active_sessions` (uma linha por usuário). Um canal Realtime avisa todos os
   aparelhos: quem vê um device_id diferente do seu entende que outro assumiu,
   é BLOQUEADO e tem a sincronização PAUSADA (para não sobrescrever dados).

   Requer no Supabase (execute uma vez — SQL fornecido no relatório):
     create table public.active_sessions (
       user_id uuid primary key references auth.users(id) on delete cascade,
       device_id text not null, device_label text, updated_at timestamptz default now());
     alter table public.active_sessions enable row level security;
     create policy "own_select" on public.active_sessions for select using (auth.uid()=user_id);
     create policy "own_insert" on public.active_sessions for insert with check (auth.uid()=user_id);
     create policy "own_update" on public.active_sessions for update using (auth.uid()=user_id);
     alter publication supabase_realtime add table public.active_sessions;

   Se a tabela ainda NÃO existir, o guard se desativa sozinho, sem quebrar o app
   (o bloqueio local por aba continua funcionando).
   ============================================================================ */
const SessionGuard = {
  TABLE: 'active_sessions',
  DEVICE_KEY: 'diario-estudos:device-id',
  enabled: true,        // infraestrutura disponível; pode cair para false se a tabela não existir
  singleDeviceMode: false, // multiaparelho é o padrão: CAS + merge protegem os dados sem expulsar PC/celular
  channel: null,
  _deviceId: null,
  _claimedUid: null,    // uid cuja posse foi confirmada neste aparelho
  _accessUid: null,
  _accessState: 'unknown', // unknown | checking | allowed | blocked | error | disabled
  _loginPromise: null,
  _loginPromiseUid: null,
  _handoffDraining: false,
  _handoffLast: null,
  _avisouSemTabela: false,

  accessState() {
    const CS = window.CloudStore;
    const uid = CS && CS.session && CS.session.user ? CS.session.user.id : null;
    if (!this.enabled) return 'disabled';
    if (!uid || this._accessUid !== uid) return 'unknown';
    return this._accessState || 'unknown';
  },
  canEnterNow() {
    if (!this.singleDeviceMode) return true;
    if (window.SessionLock && SessionLock.isBlocked() && SessionLock._origin === 'remote') return false;
    const s = this.accessState();
    return s === 'allowed' || s === 'disabled';
  },
  isBlockedByRemote() {
    if (!this.singleDeviceMode) return false;
    return this.accessState() === 'blocked' ||
      !!(window.SessionLock && SessionLock.isBlocked() && SessionLock._origin === 'remote');
  },

  deviceId() {
    if (this._deviceId) return this._deviceId;
    let id = null;
    try { id = localStorage.getItem(this.DEVICE_KEY); } catch (_) { _quiet(_); }
    if (!id) {
      id = (window.DB && DB._uid) ? DB._uid() : (Date.now().toString(36) + Math.random().toString(36).slice(2));
      try { localStorage.setItem(this.DEVICE_KEY, id); } catch (_) { _quiet(_); }
    }
    this._deviceId = id;
    return id;
  },
  // Rótulo legível do aparelho (aparece no aviso do outro dispositivo).
  deviceLabel() {
    try {
      const ua = navigator.userAgent || '';
      let so = 'Dispositivo';
      if (/Android/i.test(ua)) so = 'Android';
      else if (/iPhone|iPad|iPod/i.test(ua)) so = 'iPhone/iPad';
      else if (/Windows/i.test(ua)) so = 'Windows';
      else if (/Mac/i.test(ua)) so = 'Mac';
      else if (/Linux/i.test(ua)) so = 'Linux';
      let nav = 'navegador';
      if (/Edg\//i.test(ua)) nav = 'Edge';
      else if (/CriOS/i.test(ua)) nav = 'Chrome';
      else if (/FxiOS|Firefox\//i.test(ua)) nav = 'Firefox';
      else if (/Chrome\//i.test(ua)) nav = 'Chrome';
      else if (/Safari\//i.test(ua)) nav = 'Safari';
      // aparelhos Apple sem navegador específico identificado usam Safari
      if (nav === 'navegador' && (so === 'iPhone/iPad' || so === 'Mac')) nav = 'Safari';
      return so + ' · ' + nav;
    } catch (_) { return 'Dispositivo'; }
  },
  _isMissingTable(err) {
    const m = ((err && (err.message || err.code || err.details)) || '').toString().toLowerCase();
    return m.includes('active_sessions') || m.includes('does not exist') || m.includes('42p01') ||
           m.includes('could not find the table') || m.includes('schema cache');
  },
  _disable(err) {
    this.enabled = false;
    this._accessState = 'disabled';
    this._loginPromise = null;
    this._loginPromiseUid = null;
    this._unsub();
    if (!this._avisouSemTabela) {
      this._avisouSemTabela = true;
      console.info('[SessionGuard] tabela active_sessions ausente — login único entre dispositivos desligado. Rode o SQL do relatório para ativar. Detalhe:', err && (err.message || err));
    }
  },

  // Chamado pelo CloudStore quando há sessão (login ou sessão restaurada).
  // Esta PROMISE é também a barreira de entrada: perfil nenhum deve ser exibido
  // ou hidratado enquanto a posse da sessão ainda estiver indefinida.
  async onLogin() {
    if (!this.enabled) return { ok: true, status: 'disabled' };
    const CS = window.CloudStore;
    if (!CS || !CS.isReady() || !CS.isLoggedIn()) return { ok: false, status: 'offline' };
    const uid = CS.session.user.id;
    /* Multiaparelho: não existe "dono exclusivo" da conta. O controle de
       concorrência fica onde deve ficar — nas revisões/merges dos dados. Isso
       evita PC e celular ficarem se expulsando e transformando uma simples
       exclusão em envio bloqueado + spinner vermelho. */
    if (!this.singleDeviceMode) {
      this._accessUid = uid;
      this._accessState = 'allowed';
      this._claimedUid = uid;
      try {
        if (window.SessionLock && SessionLock.isBlocked() && SessionLock._origin === 'remote') SessionLock.unblock();
      } catch (_) { _quiet(_); }
      return { ok: true, status: 'allowed', multiDevice: true };
    }
    this.subscribe(uid);

    if (window.SessionLock && SessionLock.isBlocked() && SessionLock._origin === 'remote') {
      this._accessUid = uid;
      this._accessState = 'blocked';
      return { ok: false, blocked: true, status: 'blocked' };
    }
    if (this._accessUid === uid && this._accessState === 'allowed') {
      return { ok: true, status: 'allowed' };
    }
    if (this._accessUid === uid && this._accessState === 'blocked') {
      return { ok: false, blocked: true, status: 'blocked' };
    }
    if (this._loginPromise && this._loginPromiseUid === uid) return this._loginPromise;

    this._accessUid = uid;
    this._accessState = 'checking';
    this._loginPromiseUid = uid;
    const p = (async () => {
      /* Restaurar a sessão NÃO é um takeover. Primeiro consultamos quem possui a
         conta. Se outro aparelho está ativo, este é bloqueado e não toca na linha.
         Só uma conta livre ou já pertencente a este device é renovada. */
      try {
        const { data, error } = await CS.client.from(this.TABLE)
          .select('device_id,device_label').eq('user_id', uid).maybeSingle();
        if (error) {
          if (this._isMissingTable(error)) {
            this._disable(error);
            return { ok: true, status: 'disabled' };
          }
          this._accessState = 'error';
          console.warn('[SessionGuard] verificação inicial falhou', error);
          return { ok: false, status: 'error', error };
        }
        if (data && data.device_id && data.device_id !== this.deviceId()) {
          this._accessState = 'blocked';
          this._takenBy(data);
          return { ok: false, blocked: true, status: 'blocked', row: data };
        }
        const ok = await this.claim(uid);
        if (ok) return { ok: true, status: 'allowed' };
        this._accessState = 'error';
        return { ok: false, status: 'error' };
      } catch (err) {
        if (this._isMissingTable(err)) {
          this._disable(err);
          return { ok: true, status: 'disabled' };
        }
        this._accessState = 'error';
        console.warn('[SessionGuard] verificação inicial erro', err);
        return { ok: false, status: 'error', error: err };
      }
    })();
    this._loginPromise = p;
    try { return await p; }
    finally {
      if (this._loginPromise === p) {
        this._loginPromise = null;
        this._loginPromiseUid = null;
      }
    }
  },
  onLogout() {
    this._claimedUid = null;
    this._accessUid = null;
    this._accessState = 'unknown';
    this._loginPromise = null;
    this._loginPromiseUid = null;
    this._unsub();
    if (window.SessionLock && SessionLock.isBlocked() && SessionLock._origin === 'remote') SessionLock.unblock();
  },

  // Grava este device como o dono ativo da conta (derruba os demais).
  async claim(uid) {
    if (!this.enabled) return false;
    const CS = window.CloudStore;
    if (!CS || !CS.isReady() || !CS.isLoggedIn()) return false;
    uid = uid || CS.session.user.id;
    try {
      const { error } = await CS.client.from(this.TABLE)
        .upsert({ user_id: uid, device_id: this.deviceId(), device_label: this.deviceLabel(), updated_at: new Date().toISOString() },
                { onConflict: 'user_id' });
      if (error) {
        if (this._isMissingTable(error)) this._disable(error);
        else { this._accessState = 'error'; console.warn('[SessionGuard] claim falhou', error); }
        return false;
      }
      this._claimedUid = uid;
      this._accessUid = uid;
      this._accessState = 'allowed';
      return true;
    } catch (err) {
      if (this._isMissingTable(err)) this._disable(err);
      else { this._accessState = 'error'; console.warn('[SessionGuard] claim erro', err); }
      return false;
    }
  },

  // Verifica quem é o dono atual (na entrada, antes mesmo do primeiro evento realtime).
  async check(uid) {
    if (!this.enabled || !this.singleDeviceMode) return;
    const CS = window.CloudStore;
    if (!CS || !CS.isReady() || !CS.isLoggedIn()) return;
    uid = uid || CS.session.user.id;
    try {
      const { data, error } = await CS.client.from(this.TABLE).select('device_id,device_label').eq('user_id', uid).maybeSingle();
      if (error) { if (this._isMissingTable(error)) this._disable(error); return; }
      if (data && data.device_id && data.device_id !== this.deviceId()) {
        this._accessUid = uid;
        this._accessState = 'blocked';
        this._takenBy({ device_id: data.device_id, device_label: data.device_label });
      } else if (data && data.device_id === this.deviceId() &&
                 !(window.SessionLock && SessionLock.isBlocked() && SessionLock._origin === 'remote')) {
        this._accessUid = uid;
        this._accessState = 'allowed';
        this._claimedUid = uid;
      }
    } catch (err) { if (this._isMissingTable(err)) this._disable(err); }
  },

  subscribe(uid) {
    if (!this.enabled || !this.singleDeviceMode || this.channel) return;
    const CS = window.CloudStore;
    if (!CS || !CS.isReady()) return;
    try {
      this.channel = CS.client.channel('sess_guard')
        .on('postgres_changes', { event: '*', schema: 'public', table: this.TABLE, filter: 'user_id=eq.' + uid }, (p) => {
          const row = p.new || p.old || {};
          if (!row.device_id) return;
          if (row.device_id !== this.deviceId()) {
            this._accessUid = uid;
            this._accessState = 'blocked';
            this._takenBy(row);
          } else if (!(window.SessionLock && SessionLock.isBlocked() && SessionLock._origin === 'remote')) {
            this._accessUid = uid;
            this._accessState = 'allowed';
            this._claimedUid = uid;
            /* Não fechamos automaticamente um bloqueio REMOTO só porque chegou
               um evento com nosso device_id. O overlay só some após takeover
               explícito confirmado; assim nenhum claim concorrente ou evento
               tardio decide sozinho que a pessoa "continuou neste aparelho". */
          }
          // se a tela de Configurações estiver aberta, reflete a mudança na hora
          try { const cfg = document.getElementById('screen-config'); if (cfg && cfg.classList.contains('active') && window.CloudUI) CloudUI.renderSessions(); } catch (_) { _quiet(_); }
        })
        .subscribe((status) => { if (status === 'SUBSCRIBED') this.check(uid); });
    } catch (e) { console.warn('[SessionGuard] realtime indisponível', e); }
  },
  _unsub() {
    if (this.channel) { try { window.CloudStore.client.removeChannel(this.channel); } catch (_) { _quiet(_); } this.channel = null; }
  },

  // Outro aparelho assumiu: bloqueia NOVAS ações aqui, mas entrega primeiro
  // a fila SQL que já estava comprovadamente gravada neste aparelho.
  _takenBy(row) {
    if (!this.singleDeviceMode) {
      this._accessState = 'allowed';
      try {
        if (window.SessionLock && SessionLock.isBlocked() && SessionLock._origin === 'remote') {
          SessionLock.unblock();
        }
      } catch (e) { _quiet(e, 'session-unblock'); }
      return;
    }

    try {
      const CS = window.CloudStore;
      const uid = CS && CS.session && CS.session.user ? CS.session.user.id : null;
      if (uid) this._accessUid = uid;
      this._accessState = 'blocked';
    } catch (e) { _quiet(e, 'session-mark-blocked'); }

    if (window.SessionLock) SessionLock.block('remote', { label: row.device_label });

    /* Não existe mais fila SQL local durável. Se uma operação SQL já estava em
       voo, apenas aguardamos a fila relacional terminar e refletimos o resultado.
       O bloqueio continua imediato: nenhuma nova edição é autorizada. */
    try {
      const RS = window.RelationalStore;
      const pendentes = RS && RS.pendingCount ? RS.pendingCount() : 0;
      if (RS && pendentes > 0) {
        this._handoffDraining = true;
        this._handoffLast = {
          em: Date.now(), perfil: ProfileManager.getActiveProfileId(),
          total: pendentes, status: 'enviando'
        };
        if (window.CloudUI) {
          CloudUI.refreshSyncBtn('syncing', 'Finalizando gravação no banco antes de pausar…');
        }
        Promise.resolve(RS.flush()).then(() => {
          this._handoffDraining = false;
          const resta = RS.pendingCount ? RS.pendingCount() : 0;
          this._handoffLast = {
            em: Date.now(), perfil: ProfileManager.getActiveProfileId(),
            total: pendentes, status: resta ? 'pendente' : 'ok'
          };
          if (window.CloudUI) CloudUI.refreshSyncBtn();
        }).catch((e) => {
          this._handoffDraining = false;
          this._handoffLast = {
            em: Date.now(), perfil: ProfileManager.getActiveProfileId(),
            total: pendentes, status: 'erro',
            erro: String(e && (e.message || e) || 'erro')
          };
          if (window.CloudUI) {
            CloudUI.refreshSyncBtn('error', 'Banco não confirmou uma operação antes da pausa');
          }
        });
      }
    } catch (e) { _quiet(e, 'session-drain-relational'); }

    if (window.CloudUI) CloudUI.refreshSyncBtn();
  },

  // ---- Usado pela tela de Configurações ----
  // status: 'ok' (leu a linha), 'empty' (sem sessão registrada), 'disabled'
  // (tabela ausente/guard desligado), 'offline' (sem conexão/login), 'error'.
  async fetchActive() {
    if (!this.enabled) return { status: 'disabled' };
    if (!this.singleDeviceMode) return { status: 'multi', thisDeviceId: this.deviceId(), thisLabel: this.deviceLabel() };
    const CS = window.CloudStore;
    if (!CS || !CS.isReady() || !CS.isLoggedIn()) return { status: 'offline' };
    try {
      const { data, error } = await CS.client.from(this.TABLE)
        .select('device_id,device_label,updated_at').eq('user_id', CS.session.user.id).maybeSingle();
      if (error) { if (this._isMissingTable(error)) { this._disable(error); return { status: 'disabled' }; } return { status: 'error', message: error.message }; }
      if (!data || !data.device_id) return { status: 'empty' };
      return {
        status: 'ok',
        row: data,
        isThisDevice: data.device_id === this.deviceId(),
        thisDeviceId: this.deviceId(),
        thisLabel: this.deviceLabel()
      };
    } catch (err) { if (this._isMissingTable(err)) { this._disable(err); return { status: 'disabled' }; } return { status: 'error', message: err && err.message }; }
  },
  // Encerra a sessão do outro aparelho trazendo a posse para ESTE (reivindica).
  // O outro aparelho recebe o evento em tempo real e é bloqueado.
  async endRemoteAndClaimHere() {
    if (!this.singleDeviceMode) {
      this._accessState = 'allowed';
      try { if (window.SessionLock && SessionLock.isBlocked() && SessionLock._origin === 'remote') SessionLock.unblock(); } catch (_) { _quiet(_); }
      if (window.CloudUI) CloudUI.refreshSyncBtn();
      return true;
    }
    const ok = await this.claim();
    if (ok) {
      if (window.SessionLock && SessionLock.isBlocked() && SessionLock._origin === 'remote') SessionLock.unblock();
      try {
        const pid = window.ProfileManager ? ProfileManager.getActiveProfileId() : null;
        if (pid && window.CloudStore && CloudStore._drainSectionRealtimeHint) CloudStore._drainSectionRealtimeHint(pid);
      } catch (_) { _quiet(_); }
    }
    if (window.CloudUI) CloudUI.refreshSyncBtn();
    return ok;
  },

  /* 61-session-guard carrega ANTES de 63-cloud-ui, onde SessionLock nasce.
     Portanto o binding remoto não pode depender de "if (window.SessionLock)"
     executado uma única vez durante o parse deste arquivo. Esta função é
     idempotente e é chamada de novo por 63-cloud-ui logo depois de criar o lock. */
  _sessionLockBound: false,
  bindSessionLock() {
    if (this._sessionLockBound || !window.SessionLock || !SessionLock.onTakeover) return false;
    this._sessionLockBound = true;
    SessionLock.onTakeover(async (origin) => {
      if (origin !== 'remote') return;
      const ok = await SessionGuard.endRemoteAndClaimHere();
      if (ok) {
        showToast('Sessão retomada neste aparelho ✓');
        try { if (window.ProfileUI && ProfileUI.resumeAfterSessionClaim) ProfileUI.resumeAfterSessionClaim(); } catch (_) { _quiet(_); }
      } else {
        showToast('Não foi possível retomar agora — verifique a internet');
        SessionLock.block('remote', {});
      }
    });
    return true;
  }
};
window.SessionGuard = SessionGuard;
// No bundle atual SessionLock ainda não existe aqui; em ordens futuras, liga já.
try { SessionGuard.bindSessionLock(); } catch (_) { _quiet(_); }

